create temporary view new_new_cspu_${grass_region_without_quote} as
select cspu_id
from(
    select cspu_id
         ,1.0000*count(distinct b.item_id)/count(distinct a.item_id) as new_item_ratio
    from (
             select cspu_id
                  ,item_id
             from srdi_mart.dwd_sr_data_warehouse_ni_all_cspu_link_hf
             where grass_region in (${grass_region})
               and local_date = split(${ni_cspu_max_pt_${grass_region_without_quote}},'_')[0]
               and local_hour = cast(split(${ni_cspu_max_pt_${grass_region_without_quote}},'_')[1] as int)
               and item_id > 0
             group by 1,2
         )a
             left join new_item_${grass_region_without_quote} b
                       on a.item_id = b.item_id
    group by 1
)x
where new_item_ratio >= 0.8
;
--sql_divide_splitter--

