create temporary view all_cspu_link_${grass_region_without_quote} as
select cspu_id, model_id, shop_id
from (
         SELECT cspu_id, model_id, shop_id
         FROM srdi_mart.dwd_sr_data_warehouse_pb_all_cspu_link_hf
         WHERE grass_region = ${grass_region}
           and local_date = split(${pb_cspu_max_pt_${grass_region_without_quote}},'_')[0]
           and local_hour = cast(split(${pb_cspu_max_pt_${grass_region_without_quote}},'_')[1] as int)
         UNION ALL
         SELECT cspu_id, model_id, shop_id
         FROM srdi_mart.dwd_sr_data_warehouse_ni_all_cspu_link_hf
         WHERE grass_region = ${grass_region}
           and local_date = split(${ni_cspu_max_pt_${grass_region_without_quote}},'_')[0]
           and local_hour = cast(split(${ni_cspu_max_pt_${grass_region_without_quote}},'_')[1] as int)
     )x
group by 1,2,3
;
--sql_divide_splitter--

create temporary view cspu_level_step1_${grass_region_without_quote} as
select cspu_id,
       case
           when cspu_order_cnt <= 1 then 3
           when shop_cnt <= 5 then 4
           when 1.000000*cspu_order_cnt/shop_cnt >= 1 then 4
           when 1.000000*cspu_order_cnt/shop_cnt < 1 then 6
           end as cspu_type
from (
         SELECT cspu_id
              , COUNT(DISTINCT shop_id) shop_cnt
              , coalesce(SUM(order_cnt),0) cspu_order_cnt
         FROM all_cspu_link_${grass_region_without_quote} a
                  LEFT JOIN model_order_${grass_region_without_quote} b
                            ON a.model_id = b.model_id
         GROUP BY 1
)x
;
--sql_divide_splitter--

create temporary view cspu_level_step2_${grass_region_without_quote} as
SELECT a.item_id
     , b.model_id
     , CASE
           WHEN d.cspu_id IS NOT NULL THEN 1
           WHEN c.model_id IS NULL THEN 2
           WHEN e.cspu_type IS NOT NULL THEN e.cspu_type
           ELSE 8 END AS  cspu_type
FROM new_item_${grass_region_without_quote} a
LEFT JOIN new_item_active_model_${grass_region_without_quote} b
ON a.item_id = b.item_id
LEFT JOIN all_cspu_link_${grass_region_without_quote} c
ON b.model_id = c.model_id
LEFT JOIN new_new_cspu_${grass_region_without_quote} d
ON c.cspu_id = d.cspu_id
LEFT JOIN cspu_level_step1_${grass_region_without_quote} e
ON c.cspu_id = e.cspu_id
;
--sql_divide_splitter--

create temporary view cspu_level_step3_${grass_region_without_quote} as
select a.item_id
     ,cspu_type
     ,1.0000*model_cnt/all_model_cnt as model_ratio
from (
         select item_id
              ,cspu_type
              ,count(1) model_cnt
         from cspu_level_step2_${grass_region_without_quote}
         group by 1,2
     )a
inner join(
        select item_id
             ,count(1) all_model_cnt
        from cspu_level_step2_${grass_region_without_quote}
        group by 1
)b
on a.item_id = b.item_id
and b.all_model_cnt > 0
;
--sql_divide_splitter--

create temporary view cspu_level_step4_${grass_region_without_quote} as
select item_id
     ,cspu_type
from (
         SELECT item_id
              , cspu_type
              , row_number() over(partition BY item_id ORDER BY cspu_type) rnk
         FROM cspu_level_step3_${grass_region_without_quote}
         WHERE model_ratio >= 0.5
     )y
where rnk = 1
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE srdi_mart.dim_sr_data_warehouse_tc_ni_cspu_type
partition (grass_region=${grass_region},local_date=${local_date})
select a.item_id
     ,coalesce(cspu_type,8) as cspu_type
from new_item_${grass_region_without_quote} a
left join cspu_level_step4_${grass_region_without_quote} b
on a.item_id = b.item_id
;
